import{z as p,x as s,o as a,c as E,q as t,j as l,D as o,d as c,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"completion","description":"","frontmatter":{"title":"completion","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/completion.md","filePath":"cs/completion.md","lastUpdated":1791413859000}'),d={name:"cs/completion.md"};function m(_,e,A,h,B,D){const i=s("Mermaid");return a(),E("div",null,[e[2]||(e[2]=t('<h1 id="completion" tabindex="-1">completion <a class="header-anchor" href="#completion" aria-label="Permalink to &quot;completion&quot;">​</a></h1><div class="epigraph"><p>完成量表示「这件事已经发生过」：等待者睡到一次性事件，唤醒后事件仍然为真，不必再在循环里猜谓词。</p><footer>—— 据 Love, Linux Kernel Development；Hoare 管程里一次性会合的对照整理</footer></div><p><a href="/cs/monitor-condvar">上一课</a>用条件变量等任意谓词，Mesa 语义下必须循环检查。<a href="/cs/semaphore">信号量</a> 的 V 可以累计。缺口是内核里极常见的会合：<strong>completion</strong>——生产者做完初始化或 I/O，消费者 <code>wait_for_completion</code>，事件是一次性（或可再 init）的粘性真。本课钉这个窄对象，不把 RCU 请进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>wait(&amp;c)</code> 在管程里等的是「缓冲非空」这类会再变假的谓词。模块加载结束、设备探测结束、一次 DMA 做完，则「完成」一旦为真就保持，直到有人显式再清。用 condvar 也能写，但容易漏 <code>signal</code>、容易虚假唤醒后条件仍假。completion：内部计数或标志 + 等待队列，<code>complete</code> 后后来的 wait 立即通过。缺口不是再讲 Mesa 循环，而是这种<strong>粘性事件</strong>。</p><p><span class="marginnote">术语翻译：会合（rendezvous）就是两个执行流约定在同一个点碰头——一方等「事情做完了」，另一方负责宣布「事情做完了」。粘性指事件一旦发生就被记住：哪怕是后来才到的等待者，也不用再等，直接通过。</span></p><p><span class="marginnote"><code>complete_all</code> 唤醒当前所有等待者并把完成态留下；之后再 wait 的人也直接过。再武装需要 <code>reinit_completion</code>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明 <code>struct completion</code>。消费者 <code>wait_for_completion</code>：若已完成则返回，否则睡。生产者 <code>complete</code>：置完成，唤醒。可中断版本对接<a href="/cs/restart-syscall">重启系统调用</a> 与信号。超时版本失败则调用方处理；事件仍可能稍后到来，须规定是否还 complete。</p>',9)),(a(),l(n,null,{default:o(()=>[r(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22wait_for_completion%22%5D%20--%3E%20S%5B%22%E6%9C%AA%E5%AE%8C%E6%88%90%E5%88%99%E7%9D%A1%E7%9C%A0%22%5D%0A%20%20C%5B%22complete%22%5D%20--%3E%20DONE%5B%22%E7%B2%98%E6%80%A7%E5%AE%8C%E6%88%90%E6%80%81%22%5D%0A%20%20DONE%20--%3E%20W%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t('<p>与 IRQ：<a href="/cs/interrupt-bottom-half">中断下半部</a> 里可以 <code>complete</code>，等待者必须是线程上下文。</p><p><span class="marginnote">直觉类比：completion 像快递柜——<code>complete</code> 是快递入柜，<code>wait</code> 是凭码取件；快递先到、人后到照样取得到（完成态粘着）。条件变量更像在收发室干等管理员喊名字：喊的时候你恰好不在，就得反复回来问（Mesa 循环检查谓词）。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>completion 把「一次性会合」从通用管程里拆出来，减少谓词错误。它不是锁：完成不保护数据结构的互斥，只同步「可以开始用」。若完成前数据要可见，生产者在 <code>complete</code> 前要有 release 语义，消费者 wait 返回后 acquire——<a href="/cs/memory-barrier-os">内存屏障</a> 已给出。</p>',4)),(a(),l(n,null,{default:o(()=>[r(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22complete%20%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20ST%5B%22%E7%B2%98%E6%80%A7%E5%AE%8C%E6%88%90%E6%80%81%E4%BF%9D%E6%8C%81%E4%B8%BA%E7%9C%9F%22%5D%0A%20%20W1%5B%22%E5%85%88%E5%88%B0%E7%9A%84%20wait%22%5D%20--%3E%20CHK%7B%22%E5%AE%8C%E6%88%90%E6%80%81%E5%B7%B2%E7%BD%AE%3F%22%7D%0A%20%20CHK%20--%3E%7C%22%E5%90%A6%22%7C%20SLEEP%5B%22%E7%9D%A1%E5%85%A5%E7%AD%89%E5%BE%85%E9%98%9F%E5%88%97%22%5D%0A%20%20ST%20--%3E%20WAKE%5B%22%E5%94%A4%E9%86%92%E9%98%9F%E5%88%97%E4%B8%AD%E7%9A%84%E7%AD%89%E5%BE%85%E8%80%85%22%5D%0A%20%20W2%5B%22%E5%90%8E%E5%88%B0%E7%9A%84%20wait%22%5D%20--%3E%20PASS%5B%22%E8%A7%81%E5%AE%8C%E6%88%90%E6%80%81%E5%B7%B2%E7%BD%AE%2C%20%E7%AB%8B%E5%8D%B3%E9%80%9A%E8%BF%87%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[c(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<p><span class="marginnote">常见误区：初学者容易把 completion 当锁用。它不做互斥——完成态只回答「初始化做完了吗」，不保护任何数据结构；多个线程同时从 wait 返回后仍会一起动共享数据。要护数据得另配互斥锁；而 <code>complete</code> 前的写入要被 wait 返回后的读者看见，靠的是 release/acquire 内存序。</span></p><p>多次 <code>complete</code> 对只 wait 一次的人通常只多算一次；语义以所用内核文档为准，主干只要求一次性事件不要靠「多 V 几次」来凑。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 <code>wait_for_completion_*</code> 变体当手册。屏障、RCU 同步不是 completion：RCU 等的是「所有读者离开」，下一课。也不把 pthread_barrier 的 N 人会合写成同一对象。</p><p>后课默认：一次性事件用 completion。读多写少、读者不能睡也不能重试撕数据时，下一课 RCU 读者。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>completion：粘性「已发生」；wait 在线程，complete 可在下半部。</li><li>不替代互斥，只做会合。</li><li>无锁只读遍历是 RCU 课。</li><li>出处：Love, <em>LKD</em>。</li></ul>',7))])}const C=p(d,[["render",m]]);export{u as __pageData,C as default};
